"""Codemap: a compact map of source files and their public symbols (spec 008)."""
from __future__ import annotations

import posixpath
import re

from agentkit import _git
from agentkit.util import glob_match

_HEADER = ["# Code map", "",
           "Generated by `agentkit codemap`; do not edit by hand (run it again instead).", ""]
_MAX_ENTRY = 240
_MAX_LISTED = 10


def _files(cfg) -> list[str]:
    """R008-01: tracked or untracked, non-ignored files matching the source globs."""
    source = list(cfg.profile.get("source_globs") or [])
    build_out = list(cfg.profile.get("build_output_globs") or [])
    own = cfg.path("codemap").replace("\\", "/").lower()
    out = []
    for rel in _git.repo_files(cfg.root):
        if rel == ".agentkit" or rel.startswith(".agentkit/") or rel.lower() == own:
            continue
        if glob_match(rel, source) and not glob_match(rel, build_out):
            out.append(rel)
    # One heading per directory (R008-03): directories in order, files sorted inside each.
    return sorted(out, key=lambda rel: (posixpath.dirname(rel), rel))


def _regexes(cfg) -> list[re.Pattern]:
    table = cfg.profile.get("codemap") or {}
    return [re.compile(p, re.M) for p in table.get("symbol_regexes") or []]


def _symbols(text: str, regexes: list[re.Pattern]) -> list[str]:
    """R008-02: the `name` group, else the last group; once each, by position in the file."""
    found = []
    for rx in regexes:
        for m in rx.finditer(text):
            if "name" in rx.groupindex:
                name, pos = m.group("name"), m.start("name")
            elif rx.groups:
                name, pos = m.group(rx.groups), m.start(rx.groups)
            else:  # no group at all: the whole match
                name, pos = m.group(0), m.start()
            if name:
                found.append((pos, name))
    seen, out = set(), []
    for _, name in sorted(found, key=lambda x: x[0]):
        if name not in seen:
            seen.add(name)
            out.append(name)
    return out


def _entry(name: str, symbols: list[str]) -> str:
    line = f"- {name}: {', '.join(symbols)}" if symbols else f"- {name}"
    return line if len(line) <= _MAX_ENTRY else line[:_MAX_ENTRY - 3] + "..."  # R008-04


def _entries(cfg) -> list[tuple[str, str]]:
    regexes = _regexes(cfg)
    out = []
    for rel in _files(cfg):
        try:
            text = (cfg.root / rel).read_bytes().decode("utf-8", "replace")
        except OSError:
            continue
        out.append((rel, _entry(posixpath.basename(rel), _symbols(text, regexes))))
    return out


def build(cfg) -> str:
    lines = list(_HEADER)
    current = None
    for rel, entry in _entries(cfg):
        directory = posixpath.dirname(rel) or "."
        if directory != current:
            if current is not None:
                lines.append("")
            lines += [f"## {directory}", ""]
            current = directory
        lines.append(entry)
    while lines and lines[-1] == "":
        lines.pop()
    return "\n".join(lines) + "\n"  # R008-06


def _path(cfg):
    return cfg.root / cfg.path("codemap")


def _has_sources(cfg) -> bool:
    return bool(cfg.profile.get("source_globs"))


def write(cfg, check=False) -> bool:
    """Bring the map up to date (R008-07), or with check=True only compare (R008-08).
    Returns True when the map on disk is current."""
    if not _has_sources(cfg):
        return True  # R008-11
    path = _path(cfg)
    content = build(cfg).encode("utf-8")
    current = path.read_bytes() if path.is_file() else None
    if current == content:
        return True
    if check:
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(content)
    return True


def _parse(text: str) -> dict[str, str]:
    """{path: entry} from a map, to name the files whose entries changed (R008-10)."""
    out, directory = {}, "."
    for line in text.split("\n"):
        if line.startswith("## "):
            directory = line[3:].strip()
        elif line.startswith("- "):
            name = line[2:].split(":", 1)[0]
            out[name if directory == "." else f"{directory}/{name}"] = line
    return out


def _cli(cfg, check) -> int:
    rel = cfg.path("codemap")
    if not check:
        path = _path(cfg)
        before = path.read_bytes() if path.is_file() else None
        write(cfg)
        changed = path.is_file() and path.read_bytes() != before
        print(f"codemap: {'wrote' if changed else 'up to date,'} {rel}")
        return 0
    if write(cfg, check=True):
        print(f"codemap: {rel} is up to date")
        return 0
    path = _path(cfg)
    old = _parse(path.read_bytes().decode("utf-8", "replace")) if path.is_file() else {}
    new = _parse(build(cfg))
    changed = sorted(k for k in set(old) | set(new) if old.get(k) != new.get(k))
    state = "is missing" if not path.is_file() else "is out of date"
    print(f"codemap: {rel} {state}: run `agentkit codemap`")
    for name in changed[:_MAX_LISTED]:
        print(f"  {name}")
    if len(changed) > _MAX_LISTED:
        print(f"  ... {len(changed) - _MAX_LISTED} more")
    return 1
